import{_ as d,a8 as e,o as n,c,ah as i,K as r}from"./chunks/framework.BNwxUeRp.js";import"./chunks/theme.BC7t94LL.js";const D=JSON.parse('{"title":"Docker 核心概念","description":"","frontmatter":{"title":"Docker 核心概念","abstract":"Docker 容器化的镜像、容器、仓库三大核心概念，涵盖与虚拟机的对比及联合文件系统、命名空间、控制组等底层机制。","created":"2026-07-10T00:00:00.000Z","tags":["Docker","容器","DevOps"],"type":"概念解释","category":["🛠️ 工程工具","容器与部署"]},"headers":[],"relativePath":"vault/Knowledge/Engineering/Docker 核心概念.md","filePath":"vault/Knowledge/Engineering/Docker 核心概念.md","lastUpdated":1790655645000}'),s={name:"vault/Knowledge/Engineering/Docker 核心概念.md"};function l(h,t,b,k,_,p){const a=e("NolebaseGitContributors"),o=e("NolebaseGitChangelog");return n(),c("div",null,[t[0]||(t[0]=i('<h1 id="docker-核心概念" tabindex="-1">Docker 核心概念 <a class="header-anchor" href="#docker-核心概念" aria-label="Permalink to “Docker 核心概念”">​</a></h1><p>Docker 是容器化平台，通过 OS 级虚拟化实现应用的轻量打包和隔离运行。</p><h2 id="三大核心" tabindex="-1">三大核心 <a class="header-anchor" href="#三大核心" aria-label="Permalink to “三大核心”">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>说明</th><th>类比</th></tr></thead><tbody><tr><td>镜像（Image）</td><td>只读模板，含运行环境和代码</td><td>类（Class）</td></tr><tr><td>容器（Container）</td><td>镜像的运行实例，隔离的文件系统和进程</td><td>对象（Instance）</td></tr><tr><td>仓库（Registry）</td><td>存储和分发镜像</td><td>Docker Hub / 私有 Registry</td></tr></tbody></table><h2 id="docker-与虚拟机对比" tabindex="-1">Docker 与虚拟机对比 <a class="header-anchor" href="#docker-与虚拟机对比" aria-label="Permalink to “Docker 与虚拟机对比”">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>Docker</th><th>虚拟机</th></tr></thead><tbody><tr><td>虚拟化层</td><td>OS 级（共享宿主机内核）</td><td>硬件级（Hypervisor + 完整 Guest OS）</td></tr><tr><td>启动时间</td><td>秒级</td><td>分钟级</td></tr><tr><td>磁盘占用</td><td>MB 级</td><td>GB 级</td></tr><tr><td>隔离性</td><td>进程级</td><td>强隔离（独立内核）</td></tr></tbody></table><h2 id="关键机制" tabindex="-1">关键机制 <a class="header-anchor" href="#关键机制" aria-label="Permalink to “关键机制”">​</a></h2><ul><li><strong>联合文件系统（UnionFS）</strong>：分层构建镜像，共享底层 layer，修改只写顶层</li><li><strong>命名空间（Namespace）</strong>：PID / Net / Mount / User 等隔离</li><li><strong>控制组（Cgroups）</strong>：限制 CPU、内存、IO 等资源</li></ul><h2 id="核心流程" tabindex="-1">核心流程 <a class="header-anchor" href="#核心流程" aria-label="Permalink to “核心流程”">​</a></h2><p><code>Dockerfile</code> → <code>docker build</code> 生成 Image → <code>docker run</code> 启动 Container。</p><p>编排：单机用 <code>docker-compose</code>，集群用 <code>Kubernetes</code>（K8s）。</p>',11)),r(a),r(o)])}const u=d(s,[["render",l]]);export{D as __pageData,u as default};
